pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    let max_depth = (len as f64).log2() as usize * 2;
    introsort(arr, 0, len - 1, max_depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    if high <= low { return; }
    let n = high - low + 1;
    if n <= 16 {
        insertion_sort_range(arr, low, high);
        return;
    }
    if depth == 0 {
        heapsort_range(arr, low, high);
        return;
    }
    let p = partition_mo3(arr, low, high);
    if p > 0 { introsort(arr, low, p.saturating_sub(1), depth - 1); }
    introsort(arr, p + 1, high, depth - 1);
}

fn median_of_three<T: Ord>(arr: &[T], a: usize, b: usize, c: usize) -> usize {
    if arr[a] <= arr[b] {
        if arr[b] <= arr[c] { b } else if arr[a] <= arr[c] { c } else { a }
    } else {
        if arr[a] <= arr[c] { a } else if arr[b] <= arr[c] { c } else { b }
    }
}

fn partition_mo3<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize) -> usize {
    let mid = low + (high - low) / 2;
    let pivot_idx = median_of_three(arr, low, mid, high);
    arr.swap(pivot_idx, high);
    let pivot = arr[high].clone();
    let mut i = low;
    for j in low..high {
        if arr[j] <= pivot {
            arr.swap(i, j);
            i += 1;
        }
    }
    arr.swap(i, high);
    i
}

fn insertion_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    for i in (low + 1)..=high {
        let mut j = i;
        while j > low && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn heapsort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let n = high - low + 1;
    for i in (0..n / 2).rev() {
        sift_down(arr, low, i, n);
    }
    for end in (1..n).rev() {
        arr.swap(low, low + end);
        sift_down(arr, low, 0, end);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], base: usize, start: usize, len: usize) {
    let mut root = start;
    loop {
        let child = 2 * root + 1;
        if child >= len { break; }
        let swap = if child + 1 < len && arr[base + child] < arr[base + child + 1] { child + 1 } else { child };
        if arr[base + root] < arr[base + swap] {
            arr.swap(base + root, base + swap);
            root = swap;
        } else { break; }
    }
}
